  name: 'Basic',
  parameters: {
    docs: {
      description: {
        story: 'Default project table view as seen on the ProjectPage \`Active\` tab. All projects are active; the final MODEL_STORE row demonstrates the disabled action state.'
      }
    }
  },
  render: args => <RelayResolver mockResolvers={{
    Query: () => ({
      vfolder_host_permissions: mockVfolderHostPermissions,
      group_nodes: {
        edges: [{
          node: generateMockProject(1, {
            type: 'GENERAL',
            is_active: true
          })
        }, {
          node: generateMockProject(2, {
            type: 'GENERAL',
            is_active: true
          })
        }, {
          node: generateMockProject(3, {
            type: 'GENERAL',
            is_active: true
          })
        }, {
          node: generateMockProject(4, {
            type: 'GENERAL',
            is_active: true
          })
        }, {
          node: generateMockProject(5, {
            type: 'MODEL_STORE',
            is_active: true
          })
        }],
        count: 5
      }
    })
  }}>
      <QueryResolver {...args} />
    </RelayResolver>
