  name: 'WithSorting',
  parameters: {
    docs: {
      description: {
        story: 'Demonstrates sorting functionality. Click column headers to sort by name, domain, created date, etc.'
      }
    }
  },
  render: () => {
    const [order, setOrder] = useState<(typeof availableProjectSorterValues)[number] | null>(null);
    return <div>
        <div style={{
        marginBottom: 16,
        padding: 12,
        background: '#f5f5f5'
      }}>
          <strong>Current Order:</strong> {order || 'None'}
        </div>
        <RelayResolver mockResolvers={{
        Query: () => ({
          vfolder_host_permissions: mockVfolderHostPermissions,
          group_nodes: {
            edges: [{
              node: generateMockProject(1, {
                name: 'alpha-project',
                created_at: new Date('2024-01-15').toISOString()
              })
            }, {
              node: generateMockProject(2, {
                name: 'beta-project',
                created_at: new Date('2024-02-20').toISOString()
              })
            }, {
              node: generateMockProject(3, {
                name: 'gamma-project',
                created_at: new Date('2024-03-10').toISOString()
              })
            }],
            count: 3
          }
        })
      }}>
          <QueryResolver order={order} onChangeOrder={newOrder => setOrder(newOrder)} />
        </RelayResolver>
      </div>;
  }
